from pathlib import Path
import json,html,re,base64,runpy
ROOT=Path(__file__).parent;SITE=ROOT/'site';OUT=ROOT/'wordpress';OUT.mkdir(exist_ok=True);SITE.mkdir(exist_ok=True);ARTICLES=json.loads((ROOT/'content/articles.json').read_text());ORIGIN='https://www.intactsimulation.com';REPO='https://github.com/mnswba/Intact-Simulation'
# Only public asset URLs go into generated pages; application credentials never enter source.
ASSET_BASE=ORIGIN+'/wp-content/uploads/2026/11/'
asset=json.loads((ROOT/'public-assets.json').read_text())
image=lambda name:asset.get(name+'.png',ASSET_BASE+name+'.png')
logo=ASSET_BASE+'logo.png'
CSS=(SITE/'site.css').read_text()+(ROOT/'showcase.css').read_text();RESET='html,body{margin:0!important;padding:0!important}body{background:#fff!important}.wp-site-blocks{padding:0!important}.wp-block-post-content{max-width:none!important;margin:0!important;padding:0!important}.wp-block-post-content>*{max-width:none!important}.wp-site-blocks>header,.wp-site-blocks>footer{display:none!important}'
def header():return f'''<header class="wrap nav"><a class="brand" href="/" aria-label="Intact Simulation home"><img src="{logo}" width="35" height="35" alt=""><span>Intact Simulation</span></a><nav class="nav-links" aria-label="Main navigation"><a href="/demo/">Demo</a><a href="/finished-work/">Finished Work</a><a href="/how-it-works/">How it works</a><a href="/articles/">Articles</a><a href="/contact/">Contact</a></nav><a class="button small" href="/getting-started/">Get started <span class="arrow">↗</span></a></header>'''
def footer():return f'''<footer class="wrap footer"><div class="footer-top"><div class="footer-brand"><a class="brand" href="/"><img src="{logo}" width="35" height="35" alt=""><span>Intact Simulation</span></a><p>AI-assisted CAD. Geometry you can inspect.<br>Engineering results you can question.<br>Built in the open, for curious engineers.</p></div><div><h3>Explore</h3><ul><li><a href="/demo/">Interactive demo</a></li><li><a href="/finished-work/">Finished Work</a><a href="/how-it-works/">How it works</a></li><li><a href="/articles/">Engineering articles</a></li><li><a href="/getting-started/">Install the desktop plugin</a></li></ul></div><div><h3>In the open</h3><ul><li><a href="{REPO}" target="_blank" rel="noopener">Source code ↗</a></li><li><a href="{REPO}/issues" target="_blank" rel="noopener">Issues & feedback ↗</a></li><li><a href="/privacy-data/">Privacy & data</a></li><li><a href="/contact/">Contact</a></li></ul></div></div><div class="footer-bottom"><span>© 2026 Intact Simulation</span><span>DESIGN WITH INTENT. VERIFY WITH EVIDENCE.</span><span>Open source · Apache-2.0</span></div></footer>'''
def cta():return '''<div class="wrap"><section class="cta"><div><h2>Make something worth inspecting.</h2><p>Explore the browser examples, then bring your own ideas to the desktop CAD engine. No separate model-service API key is required for the signed-in ChatGPT workflow.</p></div><a class="button" href="/getting-started/">Get the desktop plugin <span class="arrow">↗</span></a></section></div>'''
def wrap(body):return '<!-- wp:html --><style>'+RESET+CSS+'</style><div class="intact-site">'+header()+body+footer()+'</div><!-- /wp:html -->'
def pagehero(eyebrow,title,sub):return f'<section class="wrap page-hero"><span class="eyebrow">{eyebrow}</span><h1>{title}</h1><p>{sub}</p></section>'
def articlecard(a):return f'''<article class="article-card"><div class="article-meta"><span>{html.escape(a['eyebrow']).upper()}</span><span>· {a['reading_minutes']} MIN READ</span></div><h3><a href="/articles/{a['slug']}/">{html.escape(a['title'])}</a></h3><p>{html.escape(a['summary'])}</p><a class="text-link" href="/articles/{a['slug']}/">Read the guide <span>↗</span></a></article>'''
models=[('flange','01 · NATIVE SOLID','Six-hole flange','A dimensioned mechanical part with a central bore and a circular hole pattern.','80 × 80 × 8 mm'),('enclosure','02 · NATIVE ASSEMBLY','Electronics enclosure','Separate base and lid. Try explosion, component visibility and section cuts.','2 COMPONENTS'),('gyroid','03 · SAMPLED TPMS','A gyroid, made tangible','Inspect the interior of a sampled periodic structure and understand its representation.','24 mm ENVELOPE')]
modelcards=''.join(f'''<a class="model-card" href="/demo/?model={name}"><div class="model-image"><img src="{image(name)}" alt="{title} rendered from Intact example geometry" loading="lazy"><span class="tag">{tag}</span></div><div class="model-copy"><h3>{title}</h3><p>{desc}</p><div class="model-bottom"><span>{dim}</span><strong>Explore model ↗</strong></div></div></a>''' for name,tag,title,desc,dim in models)
workflow=''.join(f'<div class="step"><span class="number">0{i}</span><h3>{title}</h3><p>{text}</p></div>' for i,(title,text) in enumerate([('Describe the intent','Start with dimensions, interfaces, materials and the features that matter. AI clarifies critical missing details.'),('Build the geometry','The desktop CAD engine executes parametric Python in an isolated worker and produces actual geometry.'),('Inspect and refine','Select parts, faces or edges. Measure, section, annotate and ask AI for a precise change.'),('Test the assumptions','For supported studies, specify materials, loads and supports. Inspect solver results and convergence before drawing conclusions.')],1))
home=f'''<main><section class="wrap hero"><div><span class="eyebrow">AI-ASSISTED CAD. ENGINEERING IN VIEW.</span><h1>Your next idea,<br>in <em>three dimensions.</em></h1><p class="intro">Turn a clear brief into editable CAD. Inspect the geometry, refine it with AI, and explore supported engineering studies with real numerical solvers.</p><div class="hero-actions"><a class="button primary" href="/demo/">Explore the demo <span class="arrow">↗</span></a><a class="button" href="/how-it-works/">See how it works <span>→</span></a></div><p class="hero-note"><span class="dot"></span>Browser examples are live. Custom AI generation runs in the desktop plugin.</p></div><div class="hero-stage"><div class="stage-heading"><span>INTACT / EXAMPLE 001</span><span>NATIVE CAD PREVIEW</span></div><iframe src="/demo/?mini=1" title="Interactive prebuilt six-hole flange example" loading="eager" allow="fullscreen"></iframe><div class="stamp"><span>FLANGE ENVELOPE</span><strong>Ø80 × 8 mm</strong><span>6 × Ø6 · PCD Ø60</span></div><div class="stage-footer"><span>DRAG TO ORBIT · SCROLL TO ZOOM</span><a href="/demo/">OPEN WORKSPACE ↗</a></div></div></section><div class="wrap capability-line"><span>FROM DESIGN INTENT TO INSPECTABLE OUTPUT</span><span>PARAMETRIC CAD</span><span>GEOMETRY-AWARE EDITS</span><span>TPMS STRUCTURES</span><span>SUPPORTED 3D ANALYSIS</span></div><section class="wrap section"><div class="section-head"><div><span class="eyebrow">A FEW THINGS YOU CAN EXPLORE</span><h2>Real geometry.<br>A hands-on first look.</h2></div><p>Three authored CAD examples, ready to inspect in your browser. Section them, separate their components and download the original files.</p></div><div class="model-grid">{modelcards}</div></section><section class="soft"><div class="wrap section"><div class="section-head"><div><span class="eyebrow">THE DESIGN LOOP</span><h2>An idea is the beginning.<br>Understanding is the point.</h2></div><a class="text-link" href="/how-it-works/">Inside the workflow <span>↗</span></a></div><div class="workflow">{workflow}</div></div></section><section class="wrap section benchmark"><div><span class="eyebrow">ENGINEERING NEEDS MORE THAN A PICTURE</span><h2>A result you can trace<br>back to the assumptions.</h2><p>Our recorded 1000 N compression example connects the mesh, boundary conditions, displacement and support reaction. Compare it with the analytical answer, then inspect the real result field in the demo.</p><p>It is one reproducible linear-elastic benchmark—not a certification of an arbitrary design.</p><a class="text-link" href="/articles/reproducible-1000-newton-compression-benchmark/">Read the worked example <span>↗</span></a></div><div class="formula"><span class="eyebrow">COMPRESSION BENCHMARK / 10 × 10 × 20 mm</span><div class="equation">u = FL / EA = 0.020 mm</div><span class="verified"><span class="dot"></span>DISPLACEMENT & STRESS REFINEMENT PASSED</span><dl><dt>Applied top load</dt><dd>−1000 N · Z</dd><dt>Elastic modulus / Poisson ratio</dt><dd>10 GPa / 0</dd><dt>Bottom support reaction</dt><dd>+1000 N · Z</dd><dt>Recorded final mesh</dt><dd>208 nodes / 588 tets</dd></dl><a class="text-link" style="margin-top:25px" href="/demo/?model=benchmark">Explore the recorded result <span>↗</span></a></div></section><section class="soft"><div class="wrap section"><div class="section-head"><div><span class="eyebrow">NOTES FROM THE WORKBENCH</span><h2>Learn what is under<br>the surface.</h2></div><a class="text-link" href="/articles/">All articles <span>↗</span></a></div><div class="article-grid">{''.join(articlecard(a) for a in ARTICLES[:3])}</div></div></section><section class="section">{cta()}</section></main>'''
pages={'home':{'title':'Intact Simulation — AI CAD & Engineering','body':wrap(home)}}
pages['how-it-works']={'title':'How it works — Intact Simulation','body':wrap(pagehero('A CLEARER DESIGN PROCESS','From a brief to a model<br>you can interrogate.','A practical loop of description, geometry, inspection and evidence. Know which part runs in your browser and which part runs in the local CAD engine.')+'<main class="wrap article-layout"><aside class="article-sidebar"><strong>THE INTACT WORKFLOW</strong><span>DESCRIBE → BUILD<br>INSPECT → REFINE<br>SIMULATE → VERIFY</span><a href="/demo/">Try the examples ↗</a></aside><article class="prose">'+(ROOT/'content/how-it-works.html').read_text()+'</article></main>'+cta())}
pages['articles']={'title':'Engineering articles — Intact Simulation','body':wrap(pagehero('NOTES FROM THE WORKBENCH','Better questions.<br>Better engineering decisions.','Practical guides to AI-assisted CAD, representations, design edits and reproducible analysis. No mystery results or unsupported claims.')+'<main class="wrap section"><div class="article-grid">'+''.join(articlecard(a) for a in ARTICLES)+'</div></main>'+cta())}
for a in ARTICLES:
 pages['article-'+a['slug']]={'title':a['title'],'slug':a['slug'],'parent_slug':'articles','body':wrap(pagehero(html.escape(a['eyebrow']),html.escape(a['title']),html.escape(a['summary']))+f'<main class="wrap article-layout"><aside class="article-sidebar"><strong>ENGINEERING GUIDE</strong><span>{a["reading_minutes"]} MIN READ<br>INTACT SIMULATION</span><a href="/articles/">← All articles</a><a href="/demo/">Open the demo ↗</a></aside><article class="prose">'+a['content_html']+'</article></main>'+cta())}
getting='''<h2>Start with a browser example</h2><p>The <a href="/demo/">interactive demo</a> needs no plugin installation. It shows prebuilt CAD and a recorded analysis result. You can orbit, section, isolate and recolor parts, explore an exploded enclosure, and download the original example files.</p><h2>Build your own models on the desktop</h2><p>The desktop plugin runs native CAD and numerical tools on your computer. The supported environment is Linux x86-64 or Windows with WSL2/Ubuntu, Python 3.12–3.13, <code>uv</code> and working bubblewrap user namespaces. Native Windows and macOS execution are not currently supported.</p><div class="notice">Intact is currently distributed as an open-source development plugin. It has not been approved or listed in the public ChatGPT plugin directory. This website does not provide a hosted AI CAD backend.</div><h3>1. Get the source</h3><pre><code>git clone https://github.com/mnswba/Intact-Simulation.git\ncd Intact-Simulation</code></pre><h3>2. Prepare Linux or WSL</h3><p>Install <code>uv</code> using its official installation instructions. Inside Ubuntu/WSL:</p><pre><code>sudo apt-get update\nsudo apt-get install -y build-essential bubblewrap libgl1 libglu1-mesa libxft2</code></pre><h3>3. Install the local plugin</h3><pre><code>python3 scripts/install-chatgpt-plugin.py</code></pre><p>For the Windows ChatGPT desktop app, run the following <strong>inside WSL</strong>, replacing the Windows profile name:</p><pre><code>python3 scripts/install-chatgpt-plugin.py --windows-home /mnt/c/Users/YOUR_WINDOWS_USER</code></pre><p>The installer downloads the pinned CAD runtimes and prepares the local development connector. Restart your AI client, enable Intact in your personal plugin marketplace and open a new conversation. Viewer Ask AI needs the signed-in local OpenAI client when the host does not supply a direct component message bridge. No additional model-service API key is required for that signed-in workflow; your OpenAI account terms and usage limits apply.</p><h3>4. Try a dimensioned request</h3><div class="notice">Create an 80 mm diameter pipe flange, 8 mm thick, with a 24 mm bore and six 6 mm holes on a 60 mm bolt circle. Verify the hole positions and export STEP.</div><p>Inspect the result, select geometry and ask for a small edit. For simulations, specify the analyzed solid, material, supports, loads and required outputs. Check actual results, convergence and analysis scope.</p><h2>Source, licenses and help</h2><p>The original Intact source is Apache-2.0. Dependencies retain their own licenses. Read the repository’s installation guide, notices and limitations before deployment or redistribution.</p><ul><li><a href="https://github.com/mnswba/Intact-Simulation/blob/main/docs/install.md">Installation and troubleshooting</a></li><li><a href="https://github.com/mnswba/Intact-Simulation/blob/main/THIRD_PARTY_NOTICES.md">Dependency notices</a></li><li><a href="https://docs.astral.sh/uv/getting-started/installation/">Official uv installation instructions</a></li><li><a href="/contact/">Contact and feedback</a></li></ul>'''
pages['getting-started']={'title':'Get started — Intact Simulation','body':wrap(pagehero('THE NEXT STEP','Try an example.<br>Then build your own.','A browser demo for a first look. An open-source desktop plugin for custom geometry and supported engineering studies.')+f'<main class="wrap article-layout"><aside class="article-sidebar"><strong>CURRENT RELEASE</strong><span>v0.17.0<br>LINUX / WINDOWS + WSL2</span><a href="{REPO}">View source ↗</a></aside><article class="prose"><div class="download-box"><div><h3>Intact Simulation source</h3><p>Open-source development release · desktop runtime required</p></div><a class="button primary" href="{REPO}/archive/refs/heads/main.zip">Download source ZIP ↗</a></div>'+getting+'</article></main>')}
contact='''<main class="wrap contact-grid"><div><h2>A useful conversation starts<br>with a little context.</h2><section class="contact-card"><span class="eyebrow">GENERAL ENQUIRIES & COLLABORATION</span><h3>Have a project in mind?</h3><p>Share the design goal, the model or analysis you need, and the constraints that matter.</p><a class="email" href="mailto:samad.ncku@gmail.com?subject=Intact%20Simulation%20enquiry">samad.ncku@gmail.com ↗</a></section><section class="contact-card"><span class="eyebrow">BUG REPORTS & FEATURE REQUESTS</span><h3>Help make the tools more useful.</h3><p>Use GitHub Issues for reproducible problems, feature requests and public technical discussion.</p><a class="text-link" href="https://github.com/mnswba/Intact-Simulation/issues" target="_blank" rel="noopener">Open the issue tracker <span>↗</span></a></section><section class="contact-card"><span class="eyebrow">JUST EXPLORING?</span><h3>Start with the examples.</h3><p>Inspect a flange, separate an enclosure, section a gyroid or explore the recorded compression result.</p><a class="text-link" href="/demo/">Launch the interactive demo <span>↗</span></a></section></div><aside class="contact-note"><span class="eyebrow">A BETTER TECHNICAL BRIEF</span><h3>What to include</h3><ol><li>The part or assembly’s purpose and units.</li><li>Critical dimensions, interfaces and manufacturing constraints.</li><li>For analysis: the material, loads, supports and expected output.</li><li>For a bug: client version, minimal reproducible example and the error message.</li></ol><p style="font-size:12px">Keep confidential CAD, application passwords, access tokens and identity documents out of public GitHub issues.</p><a class="text-link" href="/articles/engineering-a-better-text-to-cad-brief/">Read the brief-writing guide <span>↗</span></a></aside></main>'''
pages['contact']={'title':'Contact — Intact Simulation','body':wrap(pagehero('LET’S MAKE THE NEXT ITERATION BETTER','Bring your questions.<br>Bring your curiosity.','Design enquiries, engineering questions, bug reports and ideas for what Intact should do next.')+contact)}
privacy='''<h2>The interactive browser demo</h2><p>The demo loads authored example geometry and recorded solver data from this website. Orbiting, sectioning, recoloring, hiding parts, explosion and visual deformation are performed in your browser. There is no CAD upload form and no live AI request in the demo. It does not run a new engineering analysis of your design.</p><h2>Hosting and WordPress</h2><p>WordPress and the hosting provider may process operational information such as IP addresses, requested URLs, browser details and security logs. Retention and security settings depend on the hosting configuration. The demo code does not add an analytics or advertising integration, but this statement is not a complete audit of the hosting provider or every WordPress plugin.</p><h2>The desktop plugin</h2><p>Desktop CAD projects, revisions and requests are stored in the configured local state directory. Using AI sends the selected request and relevant model context to the signed-in AI client/provider. This may include geometry facts, CAD source and attached references. Provider account and privacy terms apply. Intact is not a fully offline AI service.</p><h2>Downloads and external links</h2><p>Example files are public sample designs. Source and installation links may take you to GitHub or dependency documentation. Those services have their own privacy practices. Display changes in the demo do not alter downloaded native files.</p><h2>Contact and public issues</h2><p>Email enquiries go to the listed contact address. GitHub issues are public: do not include confidential models or credentials. For questions about information you have sent directly, <a href="/contact/">contact the site owner</a>. This page describes the current technical data flow; it does not promise unverified hosting retention or deletion controls.</p>'''
pages['privacy-data']={'title':'Privacy & data — Intact Simulation','body':wrap(pagehero('CLEAR DATA BOUNDARIES','Understand where<br>your information goes.','A practical description of the browser demo, local plugin and external services.')+'<main class="wrap article-layout"><aside class="article-sidebar"><strong>DATA FLOW</strong><span>UPDATED 12 NOVEMBER 2026</span></aside><article class="prose">'+privacy+'</article></main>')}
# Showcase uses original exported geometry and public media URLs only.
showcase=json.loads((ROOT/'content/showcase.json').read_text())
render_showcase=runpy.run_path(str(ROOT/'showcase-page.py'))['render_showcase']
filter_bytes=base64.b64encode((ROOT/'showcase-filter.js').read_bytes()).decode()
filter_script='<script>(function(){var s=document.createElement("script");s.textContent=new TextDecoder().decode(Uint8Array.from(atob("'+filter_bytes+'"),function(c){return c.charCodeAt(0)}));document.body.appendChild(s)})();</script>'
pages['finished-work']={'title':'Finished Work — Intact Simulation','body':wrap(render_showcase(showcase)).replace('<!-- /wp:html -->',filter_script+'<!-- /wp:html -->')}
# Build local previews and WordPress payloads. Assets are public data only.
for key,p in pages.items():
 slug=p.get('slug',key);p['slug']=slug
 payload={'title':p['title'],'slug':slug,'content':p['body'],'status':'draft','template':'blank','comment_status':'closed','ping_status':'closed'}
 (OUT/(key+'.json')).write_text(json.dumps(payload))
 local='articles/'+slug if p.get('parent_slug') else '' if key=='home' else slug
 folder=SITE/local;folder.mkdir(parents=True,exist_ok=True)
 content=p['body'].replace(ASSET_BASE+'logo.png','/assets/intact-logo.png')
 for name in ['flange','enclosure','gyroid']:content=content.replace(image(name),'/assets/'+name+'.png')
 (folder/'index.html').write_text('<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+html.escape(p['title'])+'</title></head><body>'+content+'</body></html>')
# Demo is a first-class WordPress page. The only external runtime data are the public example ZIPs.
demo=(SITE/'demo/intact-demo.html').read_text();demo_body=re.search(r'<body>(.*)</body>',demo,re.S)[1];demo_body=re.sub(r'<script.*?</script>','',demo_body,flags=re.S)
zipurls={name:asset.get(name,ASSET_BASE+name) for name in ['intact-flange.zip','intact-enclosure.zip','intact-gyroid.zip','intact-benchmark.zip']+[item['package_filename'] for item in showcase]}
script=base64.b64encode((SITE/'demo/intact-demo.js').read_bytes()).decode()
bootstrap='(function(){var a=Uint8Array.from(atob(\"'+script+'\"),function(c){return c.charCodeAt(0)}),s=document.createElement(\"script\");s.textContent=new TextDecoder().decode(a);document.body.appendChild(s)})();'
content='<!-- wp:html --><style>'+RESET+(SITE/'demo/intact-demo.css').read_text()+'</style>'+demo_body+'<script>window.INTACT_DEMO_ASSETS='+json.dumps(zipurls)+';</script><script>'+bootstrap+'</script><!-- /wp:html -->'
(OUT/'demo.json').write_text(json.dumps({'title':'Interactive CAD demo — Intact Simulation','slug':'demo','content':content,'status':'draft','template':'blank','comment_status':'closed','ping_status':'closed'}))
(SITE/'demo/index.html').write_text(demo)
(OUT/'page-index.json').write_text(json.dumps({k:{'title':p['title'],'slug':p['slug'],'parent_slug':p.get('parent_slug')} for k,p in pages.items()},indent=2))
print('Built',len(pages),'content pages plus the interactive demo. No credentials in generated content.')
